    18|    if (g_sub_count >= MAX_SUBSCRIBERS) return -1;
    19|    g_subs[g_sub_count].type = type;
    20|    g_subs[g_sub_count].cb = cb;
    21|    g_subs[g_sub_count].active = true;
    22|    g_sub_count++;
    23|    return 0;
    24|}
    25|
    26|int event_unsubscribe(EventType type, EventCallback cb) {
    27|    for (int i = 0; i < g_sub_count; i++) {
    28|        if (g_subs[i].active && g_subs[i].type == type && g_subs[i].cb == cb) {
    29|            g_subs[i].active = false;
