     2|#include "data_pipe.h"
     3|#include <string.h>
     4|#include "hal.h" // for semaphore
     5|
     6|ImuRingBuffer g_imu_ring = {0};
     7|volatile bool g_data_ready_flag = false;
     8|static ImuFrame g_shared_buffer[RING_BUF_SIZE]; // 共享内存区，零拷贝
     9|
    10|int data_pipe_push(ImuFrame *frame) {
    11|    uint16_t next = (g_imu_ring.head + 1) % RING_BUF_SIZE;
    12|    if (next == g_imu_ring.tail) {
    13|        g_imu_ring.overflow = true;
    14|        return -1; // buffer full
    15|    }
    16|    memcpy(&g_imu_ring.buffer[g_imu_ring.head], frame, sizeof(ImuFrame));
    17|    g_imu_ring.head = next;
    18|    return 0;
    19|}
    20|
    21|// 数据管道线程：每5ms被信号量唤醒，搬运最近N帧
    22|int data_pipe_transfer(void *dest, uint16_t count) {
    23|    if (count > RING_BUF_SIZE) count = RING_BUF_SIZE;
    24|    uint16_t available = (g_imu_ring.head - g_imu_ring.tail + RING_BUF_SIZE) % RING_BUF_SIZE;
    25|    if (available == 0) return 0;
    26|    if (count > available) count = available;
    27|    // 从tail开始读取count帧，DMA方式（此处模拟memcpy）
    28|    // 实际应使用DMA通道，此处简化
    29|    memcpy(dest, &g_imu_ring.buffer[g_imu_ring.tail], count * sizeof(ImuFrame));
    30|    g_imu_ring.tail = (g_imu_ring.tail + count) % RING_BUF_SIZE;
    31|    g_data_ready_flag = true; // 通知消费者
    32|    return count;
