    22|// 处理游戏结果，存储五维数据（适配后端字段名 memory / pressure）
    23|int data_model_process_result(GameResultRaw *raw) {
    24|    FiveDimData dim;
    25|    // 计算各维度（示例映射，实际根据需求调整）
    26|    dim.reaction = normalize(raw->reaction_ms, 200, 1000);
    27|    dim.focus = normalize(raw->combo, 0, 50);
    28|    dim.working_mem = normalize(raw->nb_correct * 100.0f / raw->nb_total, 0, 100);
    29|    dim.stress = 50;  // 占位，可从心率等获取
    30|    dim.flow = (uint8_t)((raw->accuracy * 100) / 2 + dim.focus / 2);
    31|
    32|    // 生成 JSON，键名改为 memory / pressure 以匹配后端 /dashboard
    33|    cJSON *root = cJSON_CreateObject();
    34|    if (root == NULL) return -1;
    35|
    36|    cJSON_AddNumberToObject(root, "reaction", dim.reaction);
    37|    cJSON_AddNumberToObject(root, "focus", dim.focus);
    38|    cJSON_AddNumberToObject(root, "memory", dim.working_mem);   // 原 working_mem → memory
    39|    cJSON_AddNumberToObject(root, "pressure", dim.stress);      // 原 stress → pressure
    40|    cJSON_AddNumberToObject(root, "flow", dim.flow);
    41|    cJSON_AddNumberToObject(root, "timestamp", raw->timestamp);
    42|
