     5|DriverDesc g_driver_table[MAX_DRIVERS] = {0};
     6|
     7|int hal_register_driver(DriverType type, const char *name, DriverOps *ops, void *priv) {
     8|    if (type >= DRV_MAX || ops == NULL) return -1;
     9|    for (int i = 0; i < MAX_DRIVERS; i++) {
    10|        if (g_driver_table[i].is_registered == false) {
    11|            g_driver_table[i].type = type;
    12|            g_driver_table[i].name = name;
    13|            g_driver_table[i].ops = *ops;
    14|            g_driver_table[i].priv = priv;
    15|            g_driver_table[i].is_registered = true;
    16|            return 0;
    17|        }
    18|    }
    19|    return -2; // table full
    20|}
    21|
