    28|    if (pwm_drv == NULL) return -1;
    29|    // 队列满，丢弃低优先级或覆盖
    30|    int next = (g_vib_tail + 1) % QUEUE_DEPTH;
    31|    if (next == g_vib_head) {
    32|        // 队列满：检查是否可覆盖最低优先级（即最大数值）
    33|        // 简单策略：丢弃新请求
    34|        return -2;
    35|    }
    36|    memcpy(&g_vib_queue[g_vib_tail], req, sizeof(VibRequest));
    37|    g_vib_tail = next;
    38|    // 若当前空闲，立即处理
    39|    if (!g_vib_busy) {
    40|        vibrate_process_next();
    41|    }
    42|    return 0;
    43|}
    44|
    45|// 内部函数：处理下一个请求（由定时器回调触发）
    46|void vibrate_process_next(void) {
    47|    if (g_vib_head == g_vib_tail) {
    48|        g_vib_busy = false;
    49|        return;
    50|    }
    51|    // 从队列中选出最高优先级（最小priority值）
    52|    int best_idx = -1;
    53|    VibPriority best_prio = VIB_PRIO_MAX;
    54|    for (int i = g_vib_head; i != g_vib_tail; i = (i+1)%QUEUE_DEPTH) {
    55|        if (g_vib_queue[i].priority < best_prio) {
    56|            best_prio = g_vib_queue[i].priority;
    57|            best_idx = i;
    58|        }
    59|    }
    60|    if (best_idx == -1) {
    61|        g_vib_busy = false;
    62|        return;
    63|    }
    64|    // 取出请求并执行（调用PWM驱动）
    65|    VibRequest req = g_vib_queue[best_idx];
    66|    // 从队列移除（将best_idx位置标记为无效，此处用移动head方式简单处理，但有空洞）
    67|    // 实际可压缩，此处简化：将最后一个元素移到best_idx
    68|    int last = (g_vib_tail - 1 + QUEUE_DEPTH) % QUEUE_DEPTH;
    69|    if (best_idx != last) {
    70|        memcpy(&g_vib_queue[best_idx], &g_vib_queue[last], sizeof(VibRequest));
    71|    }
    72|    g_vib_tail = last;
    73|    // 执行振动（调用詹诗涵的PWM接口）
    74|    if (pwm_drv && pwm_drv->ops.write) {
    75|        // 根据mode发送PWM时序
