    78|        // 启动硬件定时器，在振动结束后调用 vibrate_process_next()
    79|        // 此处简化：假设振动立即完成
    80|        g_vib_busy = false;
    81|        vibrate_process_next(); // 递归处理下一个
    82|    }
    83|}
