    27|        if (no_data_cnt >= 10) { // 100ms
    28|            no_data_cnt = 0;
    29|            // 触发告警
    30|            Event evt;
    31|            evt.type = EVT_SYNC;
    32|            evt.timestamp_ms = g_system_tick_ms;
    33|            evt.data.sync.sync_type = 1; // 告警
    34|            event_publish(&evt);
    35|            // 尝试切换采样率
    36|            // 降级：通知詹诗涵切换100Hz
