     5|#define I2C_COUNT 1
     6|#define DMA_COUNT 8
     7|#define TIMER_COUNT 4
     8|#define GPIO_COUNT 32
     9|
    10|static uint32_t g_i2c_bitmap = 0;
    11|static uint32_t g_dma_bitmap = 0;
    12|static uint32_t g_timer_bitmap = 0;
    13|static uint32_t g_gpio_bitmap = 0;
    14|
    15|void resource_map_init(void) {
    16|    g_i2c_bitmap = 0;
    17|    g_dma_bitmap = 0;
    18|    g_timer_bitmap = 0;
    19|    g_gpio_bitmap = 0;
    20|}
    21|
    22|int resource_alloc(ResourceType type) {
    23|    switch (type) {
    24|        case RES_I2C_BUS:
    25|            if (g_i2c_bitmap == 0) { g_i2c_bitmap = 1; return 0; }
    26|            break;
    27|        case RES_DMA_CH:
    28|            for (int i=0; i<DMA_COUNT; i++) {
    29|                if ((g_dma_bitmap & (1<<i)) == 0) {
    30|                    g_dma_bitmap |= (1<<i);
    31|                    return i;
    32|                }
    33|            }
    34|            break;
    35|        case RES_TIMER:
    36|            for (int i=0; i<TIMER_COUNT; i++) {
    37|                if ((g_timer_bitmap & (1<<i)) == 0) {
    38|                    g_timer_bitmap |= (1<<i);
    39|                    return i;
    40|                }
    41|            }
    42|            break;
    43|        case RES_GPIO:
    44|            for (int i=0; i<GPIO_COUNT; i++) {
    45|                if ((g_gpio_bitmap & (1<<i)) == 0) {
    46|                    g_gpio_bitmap |= (1<<i);
    47|                    return i;
    48|                }
    49|            }
    50|            break;
    51|        default: break;
    52|    }
    53|    return -1;
    54|}
    55|
    56|int resource_free(ResourceType type, int index) {
    57|    switch (type) {
    58|        case RES_I2C_BUS: if (index==0) { g_i2c_bitmap=0; return 0; } break;
    59|        case RES_DMA_CH: if (index<DMA_COUNT) { g_dma_bitmap &= ~(1<<index); return 0; } break;
    60|        case RES_TIMER: if (index<TIMER_COUNT) { g_timer_bitmap &= ~(1<<index); return 0; } break;
    61|        case RES_GPIO: if (index<GPIO_COUNT) { g_gpio_bitmap &= ~(1<<index); return 0; } break;
    62|        default: break;
    63|    }
    64|    return -1;
    65|}
    66|
    67|bool resource_check_conflict(ResourceType type, int index) {
    68|    // 检查是否已被占用
    69|    switch (type) {
    70|        case RES_I2C_BUS: return (g_i2c_bitmap & 1) != 0;
    71|        case RES_DMA_CH: return (g_dma_bitmap & (1<<index)) != 0;
    72|        case RES_TIMER: return (g_timer_bitmap & (1<<index)) != 0;
    73|        case RES_GPIO: return (g_gpio_bitmap & (1<<index)) != 0;
