/* 上电即连续采样，无需显式启动；保留接口以符合 DriverOps 规范 */
static int imu_hal_start(void)
{
  return (imu_get_state() == IMU_STATE_READY) ? 0 : -ENODEV;
}

static int imu_hal_stop(void)
{
  /* 保持连续采样：手势识别依赖不间断的数据流，故 stop 不真正停机。
   * 若需要停机，调用方应直接使用 imu_deinit()。 */
  return 0;
