static int imu_hal_deinit(void)
{
  return imu_deinit();
}

/* 通用读接口：一次读一帧（len 须 >= sizeof(struct imu_frame_s)） */
static int imu_hal_read(void *buf, uint32_t len)
{
  if (buf == NULL || len < sizeof(struct imu_frame_s))
    {
      return -EINVAL;
    }
  return imu_sample((struct imu_frame_s *)buf);
}

/* 通用写接口：IMU 无需写入（配置通过 init 完成） */
static int imu_hal_write(void *buf, uint32_t len)
{
  (void)buf; (void)len;
